package imageproof;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.util.ArrayList;
import java.util.Locale;
import java.util.Random;
import javax.imageio.ImageIO;

// Reproducible benchmark with DEVELOPMENT and HELD-OUT scenes. Everything is generated by code
// (no outside photos), so it is synthetic: it says how the rules behave on made-up scenes with
// edges, shadows, text, trees, buildings and repeated patterns, NOT how accurate they are on photographs.
//
// Leakage rule: every scene has its own seed and belongs to exactly one group. All edited versions of a
// scene are made from that scene only, so they always stay in the same group as their original.
// Development scenes use seeds 1000-1011, held-out scenes use seeds 5000-5011 and two scene families
// (CITY_NIGHT, FABRIC) that are not in the development set at all.
//
// Run: java -cp target/classes;target/test-classes imageproof.Benchmark [dev|held-out|all] [file.csv]
public class Benchmark {

    static final String[] FAMILIES = {"SKY_BUILDINGS", "FOREST", "INDOOR_TEXT", "PORTRAIT", "SMOOTH_SKY", "BRICK_REPEAT", "CLEAN_GRAPHIC"};
    static final String[] HELD_OUT_ONLY = {"CITY_NIGHT", "FABRIC"};

    // Ground truth classes.
    static final String GENUINE = "genuine";       // nothing changed (includes harmless re-saves and natural repeats)
    static final String LOCAL = "local-edit";      // a region was changed
    static final String COPY = "copy-move";        // a region was copied inside the image
    static final String GLOBAL = "global-edit";    // the whole image was changed (brightness, blur)

    static class Case {
        String group, scene, family, change, truth;
        int seed;
        BufferedImage image;
    }

    interface Pixel {
        double value(int x, int y, Random r);
    }

    static int clamp(double v) {
        return (int) Math.max(0, Math.min(255, Math.round(v)));
    }

    static BufferedImage gray(int w, int h, Random random, Pixel p) {
        BufferedImage image = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                image.setRGB(x, y, clamp(p.value(x, y, random)) * 0x010101);
            }
        }
        return image;
    }

    // Scene families. Parameters come from the seed so every scene differs in layout and brightness.
    static BufferedImage scene(String family, int seed, int w, int h) {
        Random layout = new Random(seed);
        Random noise = new Random(seed * 31L + 7);
        double base = 90 + layout.nextInt(90);
        double sigma = 2 + layout.nextInt(5);
        int a = 30 + layout.nextInt(w / 3), b = 20 + layout.nextInt(h / 3);
        if (family.equals("SKY_BUILDINGS")) {
            int horizon = h * 2 / 3;
            return gray(w, h, noise, (x, y, r) -> y < horizon ? 200 - y * 0.1 + r.nextGaussian() * 2
                    : ((x / (a + 20)) % 2 == 0 ? 70 : 110) + ((y / 24) % 2 == 0 && (x / 10) % 2 == 0 ? 35 : 0) + r.nextGaussian() * sigma);
        } else if (family.equals("FOREST")) {
            return gray(w, h, noise, (x, y, r) -> y < h / 4 ? 210 + r.nextGaussian() * 2
                    : 70 + 30 * Math.sin(x / 9.0 + seed) * Math.cos(y / 7.0) + r.nextGaussian() * (14 + sigma));
        } else if (family.equals("INDOOR_TEXT")) {
            return gray(w, h, noise, (x, y, r) -> {
                double v = 215 - 40.0 * x / w + r.nextGaussian() * 2;
                boolean line = (y / 14) % 2 == 0 && (x / 4) % 3 != 0 && x > 20 && x < w - 20 && y > 20 && y < h / 2;
                boolean shadow = x > w / 2 && y > h * 3 / 5;
                return (line ? 40 : v) - (shadow ? 45 : 0);
            });
        } else if (family.equals("PORTRAIT")) {
            return gray(w, h, noise, (x, y, r) -> {
                double dx = (x - w / 2.0) / (w / 5.0), dy = (y - h / 2.7) / (h / 4.0);
                boolean face = dx * dx + dy * dy < 1;
                boolean clothes = y > h * 0.62 && Math.abs(x - w / 2.0) < w / 3.0;
                if (face) return 170 + 15 * dx + r.nextGaussian() * 3;
                if (clothes) return base * 0.6 + 12 * Math.sin(x / 3.0) + r.nextGaussian() * 9;
                return 120 + 30 * y / (double) h + r.nextGaussian() * 3;
            });
        } else if (family.equals("SMOOTH_SKY")) {
            return gray(w, h, noise, (x, y, r) -> 235 - 90.0 * y / h + r.nextGaussian() * 1.5
                    + (x > a && x < a + 60 && y > b && y < b + 40 ? -120 : 0));
        } else if (family.equals("BRICK_REPEAT")) {
            // Naturally repeated pattern with its own slight noise on every brick (no pixel is copied).
            return gray(w, h, noise, (x, y, r) -> {
                boolean mortar = y % 24 < 3 || (x + ((y / 24) % 2) * 20) % 40 < 3;
                return (mortar ? 60 : base + ((x / 40 + y / 24) % 3) * 12) + r.nextGaussian() * (5 + sigma);
            });
        } else if (family.equals("CLEAN_GRAPHIC")) {
            // Noise-free artwork: smooth ramps and flat shapes (screenshots, diagrams, logos).
            return gray(w, h, noise, (x, y, r) -> 40 + 120.0 * x / w + 40.0 * y / h
                    + ((x - w / 2) * (x - w / 2) + (y - h / 2) * (y - h / 2) < (a + 40) * (a + 40) ? 50 : 0));
        } else if (family.equals("CITY_NIGHT")) {
            return gray(w, h, noise, (x, y, r) -> {
                boolean window = (x / 12) % 3 == 0 && (y / 16) % 2 == 0 && y > h / 3;
                double lamp = 90 * Math.exp(-((x - w * 0.7) * (x - w * 0.7) + (y - h * 0.5) * (y - h * 0.5)) / 900.0);
                return (window ? 190 : 25) + lamp + r.nextGaussian() * (3 + sigma / 2);
            });
        } else if (family.equals("FABRIC")) {
            return gray(w, h, noise, (x, y, r) -> base + 35 * Math.sin(x * 0.9) * Math.sin(y * 0.9) + r.nextGaussian() * (8 + sigma));
        }
        throw new IllegalArgumentException(family);
    }

    // ---- edits. "region" is always inside the image. -------------------------------------------

    static BufferedImage copyOf(BufferedImage src) {
        BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_RGB);
        out.getGraphics().drawImage(src, 0, 0, null);
        return out;
    }

    // Insert a foreign object: an ellipse of unrelated texture from another scene.
    static BufferedImage insertObject(BufferedImage src, int seed, int cx, int cy, int rx, int ry) {
        BufferedImage other = scene("FOREST", seed + 99991, src.getWidth(), src.getHeight());
        BufferedImage out = copyOf(src);
        for (int y = Math.max(0, cy - ry); y < Math.min(src.getHeight(), cy + ry); y++) {
            for (int x = Math.max(0, cx - rx); x < Math.min(src.getWidth(), cx + rx); x++) {
                double dx = (x - cx) / (double) rx, dy = (y - cy) / (double) ry;
                if (dx * dx + dy * dy < 1) {
                    out.setRGB(x, y, other.getRGB(x, y));
                }
            }
        }
        return out;
    }

    static BufferedImage brightnessPatch(BufferedImage src, int x0, int y0, int w, int h, int delta) {
        BufferedImage out = copyOf(src);
        for (int y = y0; y < Math.min(src.getHeight(), y0 + h); y++) {
            for (int x = x0; x < Math.min(src.getWidth(), x0 + w); x++) {
                out.setRGB(x, y, clamp((src.getRGB(x, y) & 255) + delta) * 0x010101);
            }
        }
        return out;
    }

    static BufferedImage copyMove(BufferedImage src, int sx, int sy, int w, int h, int tx, int ty) {
        BufferedImage out = copyOf(src);
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                out.setRGB(tx + x, ty + y, src.getRGB(sx + x, sy + y));
            }
        }
        return out;
    }

    static BufferedImage globalBrightness(BufferedImage src, int delta) {
        return brightnessPatch(src, 0, 0, src.getWidth(), src.getHeight(), delta);
    }

    static BufferedImage blur(BufferedImage src) {
        BufferedImage out = copyOf(src);
        for (int y = 1; y < src.getHeight() - 1; y++) {
            for (int x = 1; x < src.getWidth() - 1; x++) {
                int sum = 0;
                for (int dy = -1; dy <= 1; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        sum += src.getRGB(x + dx, y + dy) & 255;
                    }
                }
                out.setRGB(x, y, (sum / 9) * 0x010101);
            }
        }
        return out;
    }

    static BufferedImage jpeg(BufferedImage src, float quality) {
        try {
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            javax.imageio.ImageWriter writer = ImageIO.getImageWritersByFormatName("jpeg").next();
            javax.imageio.ImageWriteParam param = writer.getDefaultWriteParam();
            param.setCompressionMode(javax.imageio.ImageWriteParam.MODE_EXPLICIT);
            param.setCompressionQuality(quality);
            javax.imageio.stream.ImageOutputStream out = ImageIO.createImageOutputStream(bytes);
            writer.setOutput(out);
            writer.write(null, new javax.imageio.IIOImage(src, null, null), param);
            out.close();
            writer.dispose();
            return ImageIO.read(new ByteArrayInputStream(bytes.toByteArray()));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    static BufferedImage withAlpha(BufferedImage src) {
        BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < src.getHeight(); y++) {
            for (int x = 0; x < src.getWidth(); x++) {
                int rgb = src.getRGB(x, y) & 0xffffff;
                out.setRGB(x, y, (x < src.getWidth() / 2 && y < 24 ? 0 : 0xff000000) | rgb);
            }
        }
        return out;
    }

    static BufferedImage grayType(BufferedImage src) {
        BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_BYTE_GRAY);
        for (int y = 0; y < src.getHeight(); y++) {
            for (int x = 0; x < src.getWidth(); x++) {
                out.getRaster().setSample(x, y, 0, src.getRGB(x, y) & 255);
            }
        }
        return out;
    }

    // ---- the set -------------------------------------------------------------------------------

    static void add(ArrayList<Case> list, String group, String scene, String family, int seed, String change, String truth, BufferedImage image) {
        Case c = new Case();
        c.group = group; c.scene = scene; c.family = family; c.seed = seed;
        c.change = change; c.truth = truth; c.image = image;
        list.add(c);
    }

    // 8 scenes per group. Sizes vary. Each scene yields one genuine image and several edited versions.
    static ArrayList<Case> build(String group) {
        ArrayList<Case> list = new ArrayList<Case>();
        boolean dev = group.equals("dev");
        int firstSeed = dev ? 1000 : 5000;
        ArrayList<String> families = new ArrayList<String>();
        for (String f : FAMILIES) {
            families.add(f);
        }
        if (!dev) {
            families.add(HELD_OUT_ONLY[0]);
            families.add(HELD_OUT_ONLY[1]);
        }
        int[][] sizes = {{320, 240}, {512, 384}, {640, 480}, {400, 400}};
        for (int i = 0; i < families.size(); i++) {
            String family = families.get(i);
            int seed = firstSeed + i;
            int w = sizes[i % sizes.length][0], h = sizes[i % sizes.length][1];
            String scene = group + "-" + family.toLowerCase(Locale.ROOT) + "-" + seed;
            BufferedImage base = scene(family, seed, w, h);
            Random pick = new Random(seed * 17L);
            int px = 64 + pick.nextInt(w - 64 - 160), py = 64 + pick.nextInt(h - 64 - 140);
            add(list, group, scene, family, seed, "none", GENUINE, base);
            add(list, group, scene, family, seed, "jpeg-q75", GENUINE, jpeg(base, 0.75f));
            add(list, group, scene, family, seed, "jpeg-q40", GENUINE, jpeg(base, 0.40f));
            add(list, group, scene, family, seed, "grayscale-type", GENUINE, grayType(base));
            add(list, group, scene, family, seed, "transparent-corner", GENUINE, withAlpha(base));
            add(list, group, scene, family, seed, "insert-object", LOCAL, insertObject(base, seed, px + 50, py + 45, 48, 38));
            add(list, group, scene, family, seed, "brightness-patch+45", LOCAL, brightnessPatch(base, px, py, 112, 96, 45));
            add(list, group, scene, family, seed, "brightness-patch-45", LOCAL, brightnessPatch(base, px, py, 112, 96, -45));
            add(list, group, scene, family, seed, "copy-move-grid", COPY, copyMove(base, 16, 16, 64, 64, ((w - 96) / 8) * 8, ((h - 96) / 8) * 8));
            add(list, group, scene, family, seed, "copy-move-offgrid", COPY, copyMove(base, 21, 19, 64, 64, ((w - 96) / 8) * 8 + 3, ((h - 96) / 8) * 8 + 5));
            add(list, group, scene, family, seed, "global-brightness+40", GLOBAL, globalBrightness(base, 40));
            add(list, group, scene, family, seed, "global-blur", GLOBAL, blur(base));
            // Small version of the same scene (too few 64 px tiles for local comparisons).
            BufferedImage small = scene(family, seed, 160, 120);
            add(list, group, scene, family, seed, "small-160x120", GENUINE, small);
            add(list, group, scene, family, seed, "small-brightness-patch+45", LOCAL, brightnessPatch(small, 40, 30, 64, 56, 45));
            add(list, group, scene, family, seed, "small-insert-object", LOCAL, insertObject(small, seed, 80, 60, 26, 22));
        }
        return list;
    }

    // ---- running -------------------------------------------------------------------------------

    public static void main(String[] args) throws Exception {
        String which = args.length > 0 ? args[0] : "all";
        ArrayList<Case> cases = new ArrayList<Case>();
        if (which.equals("dev") || which.equals("all")) {
            cases.addAll(build("dev"));
        }
        if (which.equals("held-out") || which.equals("all")) {
            cases.addAll(build("held-out"));
        }
        StringBuilder csv = new StringBuilder("group,scene,family,size,change,truth,assessment,area_pct,flagged_tiles,copy_pairs,copy_coverage_pct,millis\n");
        java.util.HashMap<String, int[]> table = new java.util.HashMap<String, int[]>();
        for (Case c : cases) {
            long start = System.currentTimeMillis();
            Analysis a = Analysis.run(c.image);
            long millis = System.currentTimeMillis() - start;
            TamperingAssessment t = a.assessment;
            String area = t.areaAvailable ? String.format(Locale.ROOT, "%.1f", t.areaPercent) : "N/A";
            int tiles = t.local == null ? 0 : t.local.flaggedTiles;
            csv.append(c.group).append(',').append(c.scene).append(',').append(c.family).append(',')
                    .append(a.width).append('x').append(a.height).append(',').append(c.change).append(',').append(c.truth).append(',')
                    .append(t.outcome).append(',').append(area).append(',').append(tiles).append(',')
                    .append(a.copyMove.matches.size()).append(',')
                    .append(String.format(Locale.ROOT, "%.0f", a.copyMove.coveragePercent())).append(',').append(millis).append('\n');
            String key = c.group + "," + c.truth;
            int[] counts = table.get(key);
            if (counts == null) {
                counts = new int[3]; // possible, no-indicators, inconclusive
                table.put(key, counts);
            }
            if (t.outcome == TamperingAssessment.Outcome.POSSIBLE_TAMPERING) counts[0]++;
            else if (t.outcome == TamperingAssessment.Outcome.NO_CLEAR_INDICATORS) counts[1]++;
            else counts[2]++;
        }
        if (args.length > 1) {
            java.nio.file.Files.write(java.nio.file.Paths.get(args[1]), csv.toString().getBytes("UTF-8"));
        }
        System.out.println("group,truth,possible,no-indicators,inconclusive");
        java.util.TreeSet<String> keys = new java.util.TreeSet<String>(table.keySet());
        for (String key : keys) {
            int[] n = table.get(key);
            System.out.println(key + "," + n[0] + "," + n[1] + "," + n[2]);
        }
    }
}
